import{_ as o,o as r,c as a,a0 as e}from"./chunks/framework.L_oL6aia.js";const p=JSON.parse('{"title":"Shadowrocket（iOS）使用教程","description":"","frontmatter":{},"headers":[],"relativePath":"guide/shadowrocket.md","filePath":"guide/shadowrocket.md"}'),i={name:"guide/shadowrocket.md"};function s(l,t,n,c,h,g){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="shadowrocket-ios-使用教程" tabindex="-1">Shadowrocket（iOS）使用教程 <a class="header-anchor" href="#shadowrocket-ios-使用教程" aria-label="Permalink to &quot;Shadowrocket（iOS）使用教程&quot;">​</a></h1><p>Shadowrocket（俗称“小火箭”）是 iOS 平台上非常流行且强大的网络代理工具。界面简洁、配置灵活，非常适合初学者与进阶用户使用。</p><hr><h2 id="一、-软件下载与准备" tabindex="-1">一、 软件下载与准备 <a class="header-anchor" href="#一、-软件下载与准备" aria-label="Permalink to &quot;一、 软件下载与准备&quot;">​</a></h2><p>Shadowrocket 是一款付费软件（官方售价 <strong>$2.99</strong>），仅在<strong>非中国大陆区（如美区）</strong> App Store 上架。</p><div class="warning custom-block"><p class="custom-block-title">⚠️ 防骗提醒</p><p>App Store 中存在大量同名或图标相似的山寨恶意应用，请谨防误装。请认准官方正版图标与开发者信息，或直接通过下方官方链接跳转。</p></div><ul><li><strong>官方正版下载地址</strong>：<a href="https://apps.apple.com/us/app/shadowrocket/id932747118" target="_blank" rel="noreferrer">App Store 传送门</a></li></ul><h3 id="账号获取与登录说明" tabindex="-1">账号获取与登录说明 <a class="header-anchor" href="#账号获取与登录说明" aria-label="Permalink to &quot;账号获取与登录说明&quot;">​</a></h3><p>推荐使用<strong>美区 Apple ID</strong> 自购买断，账号与应用绑定，可永久免费更新。</p><ul><li><strong>买断账号获取</strong>：<a href="http://ios.mimy.cc" target="_blank" rel="noreferrer">点击购买美区 Apple ID</a></li></ul><div class="tip custom-block"><p class="custom-block-title">💡 登录注意事项</p><ol><li>只能在 <strong>App Store</strong> 内登录美区账号，<strong>严禁在 iPhone「设置」主界面登录</strong>，以免发生锁机风险！</li><li>登录流程：打开 App Store ➔ 点击右上角个人头像 ➔ 滑到最底部点击「退出登录」➔ 输入并登录美区账号。</li></ol></div><img src="https://img.mimy.cc/appleid.webp" width="500" alt="App Store 登录美区 Apple ID 示意图"><hr><h2 id="二、-快速使用指南" tabindex="-1">二、 快速使用指南 <a class="header-anchor" href="#二、-快速使用指南" aria-label="Permalink to &quot;二、 快速使用指南&quot;">​</a></h2><h3 id="step-1-添加订阅链接" tabindex="-1">Step 1. 添加订阅链接 <a class="header-anchor" href="#step-1-添加订阅链接" aria-label="Permalink to &quot;Step 1. 添加订阅链接&quot;">​</a></h3><ol><li>登录 <strong>fangqi 官网</strong>，在控制面板/仪表盘复制您的专属订阅链接。</li><li>打开 <strong>Shadowrocket</strong> 应用，点击右上角的 <strong><code>+</code></strong> 按钮新增配置。</li><li>将 <strong>类型（Type）</strong> 切换为 <strong><code>Subscribe</code></strong>。</li><li>在 <strong>URL</strong> 一栏粘贴刚复制的订阅链接，<strong>备注（Note）</strong> 可自定义（如：<code>fangqi</code>）。</li><li>点击右上角 <strong>完成（Save）</strong> 保存。</li></ol><img src="https://img.mimy.cc/IOS2.webp" width="300" alt="新增配置"><img src="https://img.mimy.cc/IOS3.webp" width="300" alt="选择类型 Subscribe"><img src="https://img.mimy.cc/fangqixhj111.webp" width="300" alt="粘贴链接并保存"><hr><h3 id="step-2-选择节点与开启代理" tabindex="-1">Step 2. 选择节点与开启代理 <a class="header-anchor" href="#step-2-选择节点与开启代理" aria-label="Permalink to &quot;Step 2. 选择节点与开启代理&quot;">​</a></h3><ol><li>订阅添加成功后，应用会自动刷新并展示所有可用节点。</li><li>在列表中点击选择您需要使用的<strong>目标节点</strong>。</li><li>点击页面最顶部的 <strong>未连接（开关按钮）</strong> 开启代理服务。</li><li>首次使用时，系统会弹出 <strong>“Shadowrocket 想添加 VPN 配置”</strong> 的授权提示，请点击 <strong>允许（Allow）</strong> 并完成系统面容/密码验证。</li></ol><hr><h2 id="三、-节点延迟测试-ping" tabindex="-1">三、 节点延迟测试（Ping） <a class="header-anchor" href="#三、-节点延迟测试-ping" aria-label="Permalink to &quot;三、 节点延迟测试（Ping）&quot;">​</a></h2><p>连接前建议先进行延迟测试，选择速度更快、响应更稳定的线路：</p><h3 id="方法一-批量测试所有节点-推荐" tabindex="-1">方法一：批量测试所有节点（推荐） <a class="header-anchor" href="#方法一-批量测试所有节点-推荐" aria-label="Permalink to &quot;方法一：批量测试所有节点（推荐）&quot;">​</a></h3><ol><li>打开 Shadowrocket，将连通性测试模式设置为 <strong><code>CONNECT</code></strong>。</li><li>在首页节点列表上方，点击 <strong>连通性测试</strong>。</li><li>软件会自动测试所有节点，并在节点右侧实时显示延迟数值（毫秒 ms）。</li></ol><h3 id="方法二-单个节点单独测试" tabindex="-1">方法二：单个节点单独测试 <a class="header-anchor" href="#方法二-单个节点单独测试" aria-label="Permalink to &quot;方法二：单个节点单独测试&quot;">​</a></h3><ol><li>在首页节点列表中，<strong>长按</strong> 需要测试的某一个节点。</li><li>在弹出的菜单中点击 <strong><code>Ping</code></strong> 或 <strong><code>测试</code></strong> 即可。</li></ol><div class="info custom-block"><p class="custom-block-title">📊 延迟测试结果说明</p><ul><li><strong>绿色数字（&lt; 100ms）</strong>：网络延迟极低，体验最佳。</li><li><strong>黄色 / 橙色数字（100ms - 300ms）</strong>：延迟正常，可稳定流畅使用。</li><li><strong>红色 / 超时（Timeout）</strong>：当前节点连接异常或失效，请换用其他节点。</li></ul></div><img src="https://img.mimy.cc/fangqixhj444.webp" width="300" alt="连通性测试"><img src="https://img.mimy.cc/fangqixhj222.webp" width="300" alt="节点测试结果">',32)])])}const m=o(i,[["render",s]]);export{p as __pageData,m as default};
